function validateOutputs(items, exceptions, report) {
  if (!Array.isArray(items)) throw new Error("transactions must be an array");
  if (!Array.isArray(exceptions)) throw new Error("exceptions must be an array");
  if (!Array.isArray(report)) throw new Error("report must be an array");

  for (const row of items) validateTransactionRow(row);
  for (const row of exceptions) validateTransactionRow(row);

  // exceptions must be subset with exception_reason non-null
  for (const row of exceptions) {
    if (row.exception_reason == null) throw new Error("exceptions contain unflagged row");
  }
}

module.exports = { validateOutputs };
